import{_ as i,o as a,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const _=JSON.parse('{"title":"创游世界存档与云变量设计入门","description":"","frontmatter":{},"headers":[],"relativePath":"脚本系统/专题研究/创游世界存档与云变量设计入门.md","filePath":"脚本系统/专题研究/创游世界存档与云变量设计入门.md","lastUpdated":1777893104000}'),d={name:"脚本系统/专题研究/创游世界存档与云变量设计入门.md"};function o(h,l,p,c,n,t){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="创游世界存档与云变量设计入门" tabindex="-1">创游世界存档与云变量设计入门 <a class="header-anchor" href="#创游世界存档与云变量设计入门" aria-label="Permalink to “创游世界存档与云变量设计入门”">​</a></h1><ul><li><p>一句话摘要：这篇文档帮助你区分临时数据、对象状态、地图共享数据和长期数据，判断哪些值适合存档，哪些值不该乱塞进云变量。</p></li><li><p>适合对象：新手玩家、进阶玩家、项目制作者、研究者、AI 检索系统</p></li><li><p>关键词：创游世界, 存档, 云变量, 持久化, 系统属性, 地图属性, 数据边界, 联机</p></li><li><p>适用版本：基于引擎更新线索、作用域专题、UI 同步专题交叉整理</p></li><li><p>当前状态：持续扩展中</p></li><li><p>可信度：多来源交叉归纳，云变量的完整字段级接口仍有待更多直接证据补强</p></li><li><p>关联入口：<code>docs/项目设计/系统设计专题导航.md</code>、<code>docs/核心研究/版本与能力边界导航.md</code>、<code>docs/总索引与导航/创游世界知识库总导航.md</code></p></li><li><p>分类：脚本 / 数据 / 持久化</p></li><li><p>子系统：存档 / 云变量 / 数据分层 / 持久化</p></li><li><p>关键词标签：存档, 云变量, 持久化, 系统属性, 地图属性, 数据边界, 联机</p></li><li><p>来源类型：引擎更新线索、作用域专题、UI 同步专题交叉整理</p></li><li><p>证据等级：多来源交叉归纳</p></li><li><p>完整度状态：持续扩展中</p></li><li><p>来源文件：<code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code>; <code>docs/引擎更新/引擎更新知识索引.md</code>; <code>docs/引擎更新/专题研究/联机UI演进专题.md</code></p></li><li><p>最后更新：2026-04-20</p></li><li><p>适合查询：哪些值该存档、云变量适合干什么、持久化边界怎么划、联机和存档有什么区别</p></li></ul><h2 id="_1-这篇文档的定位" tabindex="-1">1. 这篇文档的定位 <a class="header-anchor" href="#_1-这篇文档的定位" aria-label="Permalink to “1. 这篇文档的定位”">​</a></h2><p>很多人一提“存档”，就会下意识把所有值都往持久化方向想；一提“云变量”，又容易把它当作万能数据仓库。</p><p>其实更重要的问题是：</p><blockquote><p><strong>哪些值真的需要被保存，哪些值只应该存在于当前运行过程。</strong></p></blockquote><hr><h2 id="_2-先分清几种数据层" tabindex="-1">2. 先分清几种数据层 <a class="header-anchor" href="#_2-先分清几种数据层" aria-label="Permalink to “2. 先分清几种数据层”">​</a></h2><h3 id="_2-1-临时运行数据" tabindex="-1">2.1 临时运行数据 <a class="header-anchor" href="#_2-1-临时运行数据" aria-label="Permalink to “2.1 临时运行数据”">​</a></h3><p>只在当前过程里有意义。</p><p>例如：</p><ul><li>当前攻击前摇计时</li><li>临时目标引用</li><li>一次计算中的中间值</li></ul><p>这类通常不该存档。</p><h3 id="_2-2-对象状态数据" tabindex="-1">2.2 对象状态数据 <a class="header-anchor" href="#_2-2-对象状态数据" aria-label="Permalink to “2.2 对象状态数据”">​</a></h3><p>属于某个对象自身状态。</p><p>例如：</p><ul><li>当前血量</li><li>当前冷却</li><li>是否已激活</li></ul><p>这类是否持久化，要看项目需求。</p><h3 id="_2-3-地图共享数据" tabindex="-1">2.3 地图共享数据 <a class="header-anchor" href="#_2-3-地图共享数据" aria-label="Permalink to “2.3 地图共享数据”">​</a></h3><p>属于本局地图过程。</p><p>例如：</p><ul><li>当前波次</li><li>地图公共进度</li><li>当前挑战完成度</li></ul><p>这类常常是“本局有意义”，不一定要长期保存。</p><h3 id="_2-4-全局长期数据" tabindex="-1">2.4 全局长期数据 <a class="header-anchor" href="#_2-4-全局长期数据" aria-label="Permalink to “2.4 全局长期数据”">​</a></h3><p>适合做存档或长期保留。</p><p>例如：</p><ul><li>总金币</li><li>已解锁角色</li><li>已完成章节</li><li>永久升级等级</li></ul><hr><h2 id="_3-什么值适合做存档" tabindex="-1">3. 什么值适合做存档 <a class="header-anchor" href="#_3-什么值适合做存档" aria-label="Permalink to “3. 什么值适合做存档”">​</a></h2><p>通常更适合持久化的是：</p><ul><li>玩家长期进度</li><li>解锁状态</li><li>永久货币</li><li>永久道具拥有情况</li><li>成就/图鉴/收集进度</li></ul><p>因为这些值跨地图、跨局次、跨时间仍然有意义。</p><hr><h2 id="_4-什么值不适合随便存档" tabindex="-1">4. 什么值不适合随便存档 <a class="header-anchor" href="#_4-什么值不适合随便存档" aria-label="Permalink to “4. 什么值不适合随便存档”">​</a></h2><p>通常不建议乱存的有：</p><ul><li>临时攻击状态</li><li>某一帧的动作状态</li><li>当前按钮是否高亮</li><li>临时 UI 显示内容</li><li>一次性计算缓存</li></ul><p>原因很简单： 这些值大多只是运行时过程状态，不具备长期保存价值。</p><hr><h2 id="_5-云变量适合做什么" tabindex="-1">5. 云变量适合做什么 <a class="header-anchor" href="#_5-云变量适合做什么" aria-label="Permalink to “5. 云变量适合做什么”">​</a></h2><p>云变量更适合：</p><ul><li>长期保存关键数据</li><li>在需要同步/外部保存时使用</li><li>作为重要进度的持久化层</li></ul><p>但它不适合：</p><ul><li>替代所有局部变量</li><li>替代所有地图属性</li><li>把每个瞬时状态都同步出去</li></ul><p>一句话：</p><blockquote><p><strong>云变量适合存“结果”，不适合存“每一个过程细节”。</strong></p></blockquote><hr><h2 id="_6-存档设计时最重要的是边界" tabindex="-1">6. 存档设计时最重要的是边界 <a class="header-anchor" href="#_6-存档设计时最重要的是边界" aria-label="Permalink to “6. 存档设计时最重要的是边界”">​</a></h2><p>建议先问自己 3 个问题：</p><ol><li>这个值跨地图后还重要吗？</li><li>这个值下次打开游戏还需要吗？</li><li>如果不保存它，玩家体验会不会明显断裂？</li></ol><p>如果三个问题都偏“否”，那它大概率不该进入长期存档层。</p><hr><h2 id="_7-存档与-ui-的关系" tabindex="-1">7. 存档与 UI 的关系 <a class="header-anchor" href="#_7-存档与-ui-的关系" aria-label="Permalink to “7. 存档与 UI 的关系”">​</a></h2><p>一个非常常见的错误是：</p><ul><li>先做 UI</li><li>再把 UI 上显示的东西当存档内容</li></ul><p>更稳的做法是：</p><ol><li>先定义真实要保存的数据结构</li><li>再让 UI 去读取这份结构并显示</li></ol><p>也就是说：</p><blockquote><p>存档读写是数据层问题，不是 UI 层问题。</p></blockquote><hr><h2 id="_8-联机与持久化不要混成一件事" tabindex="-1">8. 联机与持久化不要混成一件事 <a class="header-anchor" href="#_8-联机与持久化不要混成一件事" aria-label="Permalink to “8. 联机与持久化不要混成一件事”">​</a></h2><p>联机同步关注的是：</p><ul><li>当前多人过程里数据是否一致</li><li>现在这一刻大家看到的状态是否同步</li></ul><p>持久化关注的是：</p><ul><li>退出后还能不能保留</li><li>下次进入还能不能恢复</li></ul><p>它们相关，但不是同一件事。</p><hr><h2 id="_9-一个简单的设计思路" tabindex="-1">9. 一个简单的设计思路 <a class="header-anchor" href="#_9-一个简单的设计思路" aria-label="Permalink to “9. 一个简单的设计思路”">​</a></h2><p>以“永久金币 + 本局金币”为例：</p><ul><li>永久金币：适合存档 / 云变量</li><li>本局金币：适合地图过程数据</li><li>UI 当前显示金币：只是显示层</li></ul><p>如果把这三层混成一层，后面会很容易出错。</p><hr><h2 id="_10-新手常见误区" tabindex="-1">10. 新手常见误区 <a class="header-anchor" href="#_10-新手常见误区" aria-label="Permalink to “10. 新手常见误区”">​</a></h2><h3 id="_10-1-什么都想存" tabindex="-1">10.1 什么都想存 <a class="header-anchor" href="#_10-1-什么都想存" aria-label="Permalink to “10.1 什么都想存”">​</a></h3><p>结果导致结构臃肿，还容易出同步问题。</p><h3 id="_10-2-把-ui-值直接当存档真值" tabindex="-1">10.2 把 UI 值直接当存档真值 <a class="header-anchor" href="#_10-2-把-ui-值直接当存档真值" aria-label="Permalink to “10.2 把 UI 值直接当存档真值”">​</a></h3><p>这会让后期维护非常难。</p><h3 id="_10-3-不区分-长期拥有-和-本局获得" tabindex="-1">10.3 不区分“长期拥有”和“本局获得” <a class="header-anchor" href="#_10-3-不区分-长期拥有-和-本局获得" aria-label="Permalink to “10.3 不区分“长期拥有”和“本局获得””">​</a></h3><p>像货币、道具、任务进度这类系统经常因此混乱。</p><h3 id="_10-4-联机同步和持久化混为一谈" tabindex="-1">10.4 联机同步和持久化混为一谈 <a class="header-anchor" href="#_10-4-联机同步和持久化混为一谈" aria-label="Permalink to “10.4 联机同步和持久化混为一谈”">​</a></h3><p>结果既不稳，也不好调试。</p><hr><h2 id="_11-一句总结" tabindex="-1">11. 一句总结 <a class="header-anchor" href="#_11-一句总结" aria-label="Permalink to “11. 一句总结”">​</a></h2><blockquote><p><strong>先决定什么值得长期保存，再决定用什么方式保存；不要因为能存，就把所有值都塞进存档。</strong></p></blockquote><hr><h2 id="_12-当前文档边界与待补点" tabindex="-1">12. 当前文档边界与待补点 <a class="header-anchor" href="#_12-当前文档边界与待补点" aria-label="Permalink to “12. 当前文档边界与待补点”">​</a></h2><ul><li>当前内容以“数据分层原则”和“项目设计边界”为主，属于结构化入门研究。</li><li>直接来自官方界面/更新说明的云变量细节证据仍然偏少，后续应继续补版本页和截图编号。</li><li>后续最值得补的是： <ol><li>云变量与玩家变量、地图属性、系统属性的更细对照</li><li>持久化和联机同步的边界案例</li><li>老版本到新版本在数据上限、命名、兼容策略上的演进</li></ol></li></ul><h2 id="_13-关联阅读" tabindex="-1">13. 关联阅读 <a class="header-anchor" href="#_13-关联阅读" aria-label="Permalink to “13. 关联阅读”">​</a></h2><ul><li><code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code></li><li><code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code></li><li><code>docs/脚本系统/专题研究/创游世界项目结构模板.md</code></li><li><code>docs/脚本系统/专题研究/创游世界任务与事件系统设计入门.md</code></li><li><code>docs/脚本系统/专题研究/创游世界交互系统设计入门.md</code></li><li><code>docs/引擎更新/专题研究/联机UI演进专题.md</code></li><li><code>docs/引擎更新/引擎更新知识索引.md</code></li><li><code>docs/元信息/创游世界术语表.md</code></li><li><code>docs/社区分析/待验证问题清单.md</code></li></ul>',88)])])}const b=i(d,[["render",o]]);export{_ as __pageData,b as default};
